input.command:
for i in $(seq 1 26); do
  [ -f /tmp/claude-1001/charts_build.log ] && { echo "LOG at check $i"; cat /tmp/claude-1001/charts_build.log | tail -8; break; }
  pgrep -f charts_build.sh >/dev/null || { echo "script exited at check $i"; break; }
  sleep 20
done
h=$(cat /tmp/claude-1001/ajcr-locks/lake.lock/pid 2>/dev/null); echo "lock pid=$h age=$(( ($(date +%s) - $(stat -c %Y /tmp/claude-1001/ajcr-locks/lake.lock 2>/dev/null || date +%s))/60 ))min"

for i in $(seq 1 27); do
  grep -q "^DONE" /tmp/claude-1001/charts_build.log 2>/dev/null && { echo "DONE at check $i"; break; }
  pgrep -f charts_build.sh >/dev/null || { echo "script gone at check $i"; break; }
  sleep 20
done
grep -E "BUILD_EXIT|RELEASED|NOT RELEASED|^DONE" /tmp/claude-1001/charts_build.log; echo "--- jobs ---"; grep -oE "\[[0-9]+/[0-9]+\]" /tmp/claude-1001/charts_build.log | tail -1; echo "--- errors ---"; grep -cE "error:" /tmp/claude-1001/charts_build.log
